#pragma once
// Accepted-state observations. Periodic unwrapping is persisted, not re-inferred on resume.
struct Track {std::array<double,2>wrapped{},unwrapped{};int has=0,continuous=1;};
struct CurrentObservation {double Q=0,x=NAN,y=NAN,ux=NAN,uy=NAN,radius=NAN,shape=NAN;int singular=0,cores=0,closed=0,ambiguous=0,single=0,continuous=0;};
int imod(int a,int n){return (a%n+n)%n;}
CurrentObservation observe_current(const std::vector<V>&a,const UserConfig&u,const CurrentSOT&d,Track&t,bool update){int nx=u.c.n[0],ny=u.c.n[1];bool periodic=u.c.pbc[0];double hx=u.c.h[0]*1e9,hy=u.c.h[1]*1e9;CurrentObservation o;std::vector<double>charge(nx*ny);auto addtriangle=[&](int ia,int ib,int ic){V x=a[ia],y=a[ib],z=a[ic];double xy=dot(x,y),yz=dot(y,z),zx=dot(z,x),det=dot(x,sot_cross(y,z)),den=1+xy+yz+zx;if(xy<=-1+1e-12||yz<=-1+1e-12||zx<=-1+1e-12||std::hypot(det,den)<=1e-12){o.singular++;return;}double q=2*std::atan2(det,den)/(4*acos(-1.));o.Q+=q;for(int k:{ia,ib,ic})charge[k]+=q/3;};
 for(int y=0;y<(periodic?ny:ny-1);y++)for(int x=0;x<(periodic?nx:nx-1);x++){int aa=x+y*nx,b=imod(x+1,nx)+y*nx,c=imod(x+1,nx)+imod(y+1,ny)*nx,dd=x+imod(y+1,ny)*nx;addtriangle(aa,b,c);addtriangle(aa,c,dd);}
 if(!o.singular&&std::abs(o.Q)>=.1){if(periodic){std::array<double,2>cs{},sn{};for(int y=0;y<ny;y++)for(int x=0;x<nx;x++){double q=charge[x+y*nx]/o.Q;cs[0]+=q*std::cos(2*acos(-1.)*(x+.5)/nx);sn[0]+=q*std::sin(2*acos(-1.)*(x+.5)/nx);cs[1]+=q*std::cos(2*acos(-1.)*(y+.5)/ny);sn[1]+=q*std::sin(2*acos(-1.)*(y+.5)/ny);}if(std::hypot(cs[0],sn[0])>1e-12&&std::hypot(cs[1],sn[1])>1e-12){double px=std::atan2(sn[0],cs[0]),py=std::atan2(sn[1],cs[1]);if(px<0)px+=2*acos(-1.);if(py<0)py+=2*acos(-1.);o.x=d.origin_nm.x+px/(2*acos(-1.))*nx*hx;o.y=d.origin_nm.y+py/(2*acos(-1.))*ny*hy;}}else{double x=0,y=0;for(int j=0;j<ny;j++)for(int i=0;i<nx;i++){x+=charge[i+j*nx]*(d.origin_nm.x+(i+.5)*hx);y+=charge[i+j*nx]*(d.origin_nm.y+(j+.5)*hy);}o.x=x/o.Q;o.y=y/o.Q;}}
 std::vector<double>zs;for(V v:a)zs.push_back(v.z);std::nth_element(zs.begin(),zs.begin()+zs.size()/2,zs.end());double bg=zs[zs.size()/2]>=0?1:-1;std::vector<char>seen(nx*ny);for(int k=0;k<nx*ny;k++){if(seen[k]||bg*a[k].z>=0)continue;int size=0;std::vector<int>todo{k};seen[k]=1;while(!todo.empty()){int q=todo.back();todo.pop_back();size++;int x=q%nx,y=q/nx;for(auto xy:std::array<std::array<int,2>,4>{{{x-1,y},{x+1,y},{x,y-1},{x,y+1}}}){int xx=xy[0],yy=xy[1];if(periodic){xx=imod(xx,nx);yy=imod(yy,ny);}if(xx>=0&&xx<nx&&yy>=0&&yy<ny){int z=xx+yy*nx;if(!seen[z]&&bg*a[z].z<0){seen[z]=1;todo.push_back(z);}}}}if(size>=4)o.cores++;}
 int sx=periodic&&std::isfinite(o.x)?nx/2-int(std::floor((o.x-d.origin_nm.x)/hx)):0,sy=periodic&&std::isfinite(o.y)?ny/2-int(std::floor((o.y-d.origin_nm.y)/hy)):0;auto value=[&](int x,int y){return a[imod(x-sx,nx)+imod(y-sy,ny)*nx].z;};int horizontal=(nx-1)*ny,edges=horizontal+nx*(ny-1);std::vector<std::array<double,2>>pos(edges);std::vector<std::vector<int>>adj(edges);
 for(int y=0;y<ny-1;y++)for(int x=0;x<nx-1;x++){double f[4]={value(x,y),value(x+1,y),value(x+1,y+1),value(x,y+1)};bool zero=false;for(double v:f)zero|=v==0;if(zero){o.ambiguous++;continue;}int ids[4]={x+y*(nx-1),horizontal+x+1+y*nx,x+(y+1)*(nx-1),horizontal+x+y*nx};int xx[4]={x,x+1,x+1,x},yy[4]={y,y,y+1,y+1};std::vector<int>cross;for(int side=0;side<4;side++){int b=(side+1)%4;if((f[side]>0)==(f[b]>0))continue;double q=f[side]/(f[side]-f[b]);pos[ids[side]]={(xx[side]+q*(xx[b]-xx[side])-(nx-1)/2.)*hx,(yy[side]+q*(yy[b]-yy[side])-(ny-1)/2.)*hy};cross.push_back(side);}auto link=[&](int p,int q){adj[ids[p]].push_back(ids[q]);adj[ids[q]].push_back(ids[p]);};if(cross.size()==2)link(cross[0],cross[1]);else if(cross.size()==4){double det=f[0]*f[2]-f[1]*f[3];if(std::abs(det)<=1e-14)o.ambiguous++;else if(det>0){link(0,1);link(2,3);}else{link(0,3);link(1,2);}}}
 std::vector<char>visited(edges);int paths=0;for(int root=0;root<edges;root++){if(visited[root]||adj[root].empty())continue;paths++;std::vector<int>v;int previous=-1,cur=root;bool closed=false;for(int guard=0;guard<=edges;guard++){if(visited[cur]){closed=cur==root;break;}visited[cur]=1;v.push_back(cur);if(adj[cur].size()!=2)break;int next=adj[cur][0]==previous?adj[cur][1]:adj[cur][0];previous=cur;cur=next;}if(!closed||v.size()<3)continue;double twice=0,cx=0,cy=0,xx=0,yy=0,xy=0;for(size_t k=0;k<v.size();k++){auto a=pos[v[k]],b=pos[v[(k+1)%v.size()]];double q=a[0]*b[1]-b[0]*a[1];twice+=q;cx+=(a[0]+b[0])*q;cy+=(a[1]+b[1])*q;xx+=(a[0]*a[0]+a[0]*b[0]+b[0]*b[0])*q;yy+=(a[1]*a[1]+a[1]*b[1]+b[1]*b[1])*q;xy+=(2*a[0]*a[1]+a[0]*b[1]+b[0]*a[1]+2*b[0]*b[1])*q;}double A=twice/2;if(std::abs(A)<1e-14)continue;cx/=6*A;cy/=6*A;xx=xx/(12*A)-cx*cx;yy=yy/(12*A)-cy*cy;xy=xy/(24*A)-cx*cy;double disc=std::hypot(xx-yy,2*xy),lo=(xx+yy-disc)/2,hi=(xx+yy+disc)/2;if(lo<=0)continue;o.closed++;o.radius=std::sqrt(std::abs(A)/acos(-1.));o.shape=std::sqrt(hi/lo)-1;}
 if(o.closed!=1){o.radius=NAN;o.shape=NAN;}o.single=!o.singular&&o.cores==1&&paths==1&&o.closed==1&&!o.ambiguous&&std::isfinite(o.x)&&(!periodic||std::abs(std::abs(o.Q)-1)<=1e-6);
 if(!o.single){t.has=0;t.continuous=0;}else if(update){if(std::isfinite(o.x)&&std::isfinite(o.y)){std::array<double,2>q{o.x,o.y};for(int k=0;k<2;k++){double delta=q[k]-t.wrapped[k],L=(k?ny*hy:nx*hx);if(periodic)delta-=std::round(delta/L)*L;t.unwrapped[k]=t.has?t.unwrapped[k]+delta:q[k];t.wrapped[k]=q[k];}t.has=1;}else{t.has=0;t.continuous=0;}}
 if(o.single&&t.has&&std::isfinite(o.x)){o.ux=t.unwrapped[0];o.uy=t.unwrapped[1];o.continuous=t.continuous;}
 return o;
}
